const Autocomplete = ({ suggestions, onSelection }) => {
  const [filteredSuggestions, setFilteredSuggestions] = useState([]);
  const [inputValue, setInputValue] = useState('');

  useEffect(() => {
    const suggestionsList = suggestions.filter(suggestion => {
      const userInput = inputValue.toLowerCase();
      return suggestion.toLowerCase().includes(userInput);
    });

    setFilteredSuggestions(suggestionsList);
  }, [inputValue, suggestions]);

  const handleInput = event => {
    setInputValue(event.target.value);
  };

  const handleSelection = suggestion => {
    onSelection(suggestion);
    setInputValue('');
  };

  return (
    <div>
      <input
        type="text"
        value={inputValue}
        onChange={handleInput}
        placeholder="Type to search"
        autoFocus
      />
      {filteredSuggestions.length > 0 && (
        <ul>
          {filteredSuggestions.map((suggestion, index) => (
            <li key={index} onClick={() => handleSelection(suggestion)}>
              {suggestion}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};

export default Autocomplete;
