```csharp
using System;
using System.Net;
using System.IO;

namespace HelloWorldHttpServer
{
    class Program
    {
        static void Main(string[] args)
        {
            // Création d'un objet HttpListener
            HttpListener listener = new HttpListener();

            // Définition de l'adresse d'écoute (hôte et port)
            listener.Prefixes.Add("http://localhost:8080/");

            // Mise en écoute du serveur HTTP
            listener.Start();

            // Boucle infinie pour écouter les requêtes
            while (true)
            {
                // Attendre une requête
                HttpListenerContext context = listener.GetContext();

                // Traitement de la requête
                HttpListenerRequest request = context.Request;
                string message = "Bonjour ! Le serveur HTTP est en ligne !";

                // Création de la réponse HTTP
                HttpListenerResponse response = context.Response;
                byte[] buffer = System.Text.Encoding.UTF8.GetBytes(message);
                response.ContentLength64 = buffer.Length;
                Stream output = response.OutputStream;
                output.Write(buffer, 0, buffer.Length);
                output.Close();

                // Fermeture de la réponse
                response.Close();
            }
        }
    }
}
```
Explications :

* Nous créons un objet `HttpListener` et définissons son prefixe (adresse d'écoute) avec `Prefixes.Add("http://localhost:8080/");`. Cela signifie que le serveur sera en écoute pour les requêtes HTTP pour l'adresse `http://localhost:8080/`.
* Nous appelons la méthode `Start()` pour mettre en écoute le serveur HTTP.
* La boucle infinie `while (true)` est utilisée pour écouter les requêtes. À chaque tour, nous appelons `GetContext()` pour obtenir la requête en cours.
* Nous traitons la requête en créant une réponse HTTP en utilisant les objets `HttpContext` et `HttpListenerResponse`. Nous écrivons le texte "Bonjour ! Le serveur HTTP est en ligne !" dans la réponse en utilisant l'encodeur UTF-8.
* Enfin, nous fermons la réponse en utilisant la méthode `Close()`.

