using namespace std;

// Define constants
const double gamma = 0.022; // in Pa
const double alpha = 20e-6; // in m
const double mu = 16e-6; // in Pa s
const double L = 50e-6; // in m
const double W = 162e-6; // in m
const double b = 30; // in m

// Define functions
double M(double z, double h, double alpha, double mu) {
  return (pow(z, 4) * pow(alpha, 4)) / (16 * mu * (3 * pow(1 + h / (z * alpha), 4) - 4 * pow(1 + h / (z * alpha), 2) + 1 - 4 * pow(1 + h / (z * alpha), 4) * log(1 + h / (z * alpha))));
}

double p(double z, double h, double alpha, double gamma, double hprime) {
  return -gamma * ((pow(hprime, 2) / (1 + pow(hprime, 2)))^(3/2) - (1 - alpha * hprime) / ((z * alpha + h) * (1 + pow(hprime, 2))^(1/2)));
}

int main() {
  // Define grid sizes
  int Nz = 100;
  double dz = 1e-6 / Nz;
  int Nt = 1000;
  double dt = 1e-6 / Nt;

  // Initialize arrays
  vector<vector<double>> h(Nz + 1, vector<double>(Nt + 1)); // height
  vector<vector<double>> p(Nz + 1, vector<double>(Nt + 1)); // pressure
  vector<double> hprime(Nz + 1); // height gradient
  vector<double> Mvec(Nz + 1); // M function values

  // Set initial conditions
  for (int i = 0; i <= Nz; ++i) {
    h[i][0] = L + W * (1 - tanh((i * dz - b) / b));
  }
  for (int i = 0; i <= Nz; ++i) {
    p[i][0] = 1100;
  }

  // Time-stepping loop
  for (int n = 0; n <= Nt; ++n) {
    double t = n * dt;
    for (int i = 1; i < Nz; ++i) {
      double hleft = h[i - 1][n];
      double hright = h[i + 1][n];
      double hcurr = h[i][n];
      double pleft = p[i - 1][n];
      double pright = p[i + 1][n];
      double pcurr = p[i][n];
      double Mleft = M(i * dz, hleft, alpha, mu);
      double Mright = M((i + 1) * dz, hright, alpha, mu);
      double Mcurr = M(i * dz, hcurr, alpha, mu);

      double dhdz = (hright - hleft) / (2 * dz);
      double hprimel = dhdz;
      double hprimer = dhdz;

      double left = (Mleft * (pcurr - pleft) - (hcurr - hleft)) / (dt * dz);
      double right = (Mright * (pright - pcurr) - (hright - hcurr)) / (dt * dz);

      double hprimenew = hprimel + dt / (dz * Mcurr) * (right - left);
      double hnew = hcurr + dt * (hprimenew - hprimel);

      h[i][n + 1] = hnew;
      p[i][n + 1] = pcurr;

      // Re-compute derivatives for next iteration
      dhdz = (hnew - hleft) / (2 * dz);
      hprimel = dhdz;
      hprimer = dhdz;
    }
  }

  // Print results
  cout << "Height and pressure at t=" << Nt * dt << "s:\n";
  for (int i = 0; i <= Nz; ++i) {
    cout << "z=" << i * dz << "m, h=" << h[i][Nt] << "m, p=" << p[i][Nt] << "Pa\n";
  }

  return 0;
}
```
