```c
#include <Windows.h>
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <random>

// Функция- požadаем, которая будет вычислять интеграл
double f(double x) {
    return x * x;
}

// Методы интегрирования
double rectangle(int n) {
    double result = 0;
    double h = 1.0 / n;
    for (int i = 0; i < n; i++) {
        result += f(i * h);
    }
    return result * h;
}

double trapezoid(int n) {
    double result = 0;
    double h = 1.0 / n;
    for (int i = 0; i < n; i++) {
        result += f(i * h) + f((i + 1) * h);
    }
    return result * h / 2;
}

double simpson(int n) {
    double result = 0;
    double h = 1.0 / n;
    for (int i = 0; i < n; i++) {
        if (i == 0 || i == n - 1) {
            result += f(i * h);
        } else if (i % 2 == 0) {
            result += 2 * f(i * h);
        } else {
            result += 4 * f(i * h);
        }
    }
    return result * h / 3;
}

// Функция- Calc для каждого потока
DWORD WINAPI CalcThreadFunc(LPVOID lpParameter) {
    int* n = (int*)lpParameter;
    std::vector<double> results;

    // Создать мьютекс для синхронизации вывода
    HANDLE mutex = CreateMutex(NULL, FALSE, NULL);
    if (mutex == NULL) {
        return 0;
    }

    // Создать цикл для n разрядов
    for (int i = 1; i <= *n; i++) {
        double result = 0;

        // Выполнить интеграл методом прямоугольников
        result += rectangle(i);
        // Выполнить интеграл методом трапеций
        result += trapezoid(i);
        // Выполнить интеграл методом Симпсона
        result += simpson(i);

        // Добавить результат в вектор
        results.push_back(result);

        // Отсчитать 10 мс для имитации задержки
        Sleep(10);
    }

    // Ожидать, пока другие потоки не закончат вычисления
    WaitForMultipleObjects(*n, NULL, TRUE, INFINITE);
    ReleaseMutex(mutex);

    // Вывести результаты
    std::lock_guard<std::mutex> lock;
    std::cout << "Results for n = " << *n << ":\n";
    for (const auto& result : results) {
        std::cout << result << " ";
    }
    std::cout << "\n";

    return 0;
}

int main() {
    int n = 8; // количество точек на интервале

    // Создать n потоков
    HANDLE threads[n];
    for (int i = 0; i < n; i++) {
        threads[i] = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)&CalcThreadFunc, &n, 0, NULL);
        if (threads[i] == NULL) {
            std::cerr << "Error creating thread\n";
            return -1;
        }
    }

    // Ожидать, пока все потоки не закончат вычисления
    WaitForMultipleObjects(n, threads, TRUE, INFINITE);

    // Закрыть потоки
    for (int i = 0; i < n; i++) {
        CloseHandle(threads[i]);
    }

    return 0;
}
```
В этой программе мы создаем n потоков, каждый из которых выполняет вычисления интеграла методами прямоугольников, трапеций и парабол (метод Симпсона) с помощью функций rectangle, trapezoid и simpson соответственно. Пока каждый поток выполняет вычисления, он использует мьютекс для синхронизации вывода результатов в стандартный вывод. Когда все потоки завершат вычисления, мы ожидаем их.exit и закрываем потоки.

Обратите внимание, что в этом примере мы используем Sleep для имитации задержок между вычислениями, чтобы усложнить вывод результатов. В реальном приложении вам может потребоваться более сложная стратегия синхронизации вывода результатов, в зависимости от вашей конкретной задачи.<|start_header_id|>assistant<|end_header_id|>

