) {
  // your handler code
}
```
**Option 2: Use the `require` statement instead of `import`**

You can stick with a single file, but use the `require` statement instead of `import`. Replace your `import` statement with:
```js
const { VercelRequest, VercelResponse } = require('@vercel/node');
