  };

  handleSignIn = (event) => {
    event.preventDefault();
    signUp({
      username: this.state.username,
      password: this.state.password,
    })
      .then((response) => {
        this.setState({ isAuthenticated: true, token: response.data.token });
      })
      .catch((error) => {
        console.error(error);
      });
  };

